validate:
(result, args) => {
  const strs = args[0];
  if (!Array.isArray(result) || result.length !== 2) return "Return a pair: [encode(strs), decode(encode(strs))].";
  const [encoded, decoded] = result;
  if (typeof encoded !== "string") return "encode must return a single string, but got " + typeof encoded + ".";
  if (!Array.isArray(decoded)) return "decode must return an array of strings.";
  if (decoded.length !== strs.length) return "Decoding gave " + decoded.length + " strings, but " + strs.length + " went in. Encoded text: " + JSON.stringify(encoded);
  for (let i = 0; i < strs.length; i++) if (decoded[i] !== strs[i]) return "String " + (i + 1) + " came back as " + JSON.stringify(decoded[i]) + " instead of " + JSON.stringify(strs[i]) + ". Encoded text: " + JSON.stringify(encoded);
  return true;
}
